function setAssistantPersona(name){assistantPersona=name;$$('[data-persona]').forEach(b=>b.classList.toggle('active',b.dataset.persona===name));const input=$("#assistantPrompt");if(input&&!input.value.trim())input.placeholder=name==="Lily"?"Lily, help me design and price a bouquet…":"Rose, tell me what needs my attention today…"}
const FEMALE_VOICE_HINTS=/samantha|victoria|karen|moira|zira|aria|jenny|ava|susan|hazel|serena|salli|joanna|kendra|kimberly|ivy|emma|amy|olivia|female|woman/i;
function availableEnglishVoices(){const voices=window.speechSynthesis?.getVoices?.()||[];const english=voices.filter(v=>/^en[-_]/i.test(v.lang||""));return english.length?english:voices}
function preferredVoice(persona){const pool=availableEnglishVoices();const saved=persona==="Rose"?localStorage.getItem("bloomRoseVoice")||"":"";if(saved){const exact=pool.find(v=>v.name===saved);if(exact)return exact}const female=pool.filter(v=>FEMALE_VOICE_HINTS.test(v.name||""));if(persona==="Rose")return female.find(v=>/samantha|victoria|karen|moira|zira|joanna|salli|serena/i.test(v.name))||female[0]||pool.find(v=>/natural|enhanced|premium/i.test(v.name))||pool[0];return female.find(v=>/aria|jenny|ava|susan|emma|olivia/i.test(v.name))||female[0]||pool[0]}
function roseVoiceRate(){return Number(localStorage.getItem("bloomRoseVoiceRate")||.9)}
function roseVoicePitch(){return Number(localStorage.getItem("bloomRoseVoicePitch")||1.08)}
function speakAssistant(text,persona,force=false){if((!force&&!$("#assistantSpeak")?.checked)||!window.speechSynthesis||!text)return;window.speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.voice=preferredVoice(persona);u.rate=persona==="Rose"?roseVoiceRate():1.02;u.pitch=persona==="Rose"?roseVoicePitch():1.12;u.volume=1;window.speechSynthesis.speak(u)}
async function runAssistant(rawPrompt,persona=assistantPersona){let prompt=(rawPrompt??$("#assistantPrompt")?.value??"").trim();if(!prompt)return toast("Ask Lily or Rose a question first");setAssistantPersona(persona);if(!new RegExp(`^${persona}\\b`,"i").test(prompt))prompt=`${persona}, ${prompt}`;const out=$("#assistantAnswer");if(!out)return toast("Assistant panel is not available on this page");out.textContent=`${persona} is thinking locally…`;try{const context=await loadAiContext();const d=await askBloomAi(prompt,persona,context);out.textContent=d.answer;speakAssistant(d.answer,d.persona||persona)}catch(e){out.textContent=`AI unavailable: ${e.message}. Bloom POS and payments are still working.`}}
