async function runContentHelper(button){const target=document.getElementById(button.dataset.aiTarget);if(!target)return;const form=button.closest("form"),fields=form?Object.fromEntries(new FormData(form)):{};const original=button.textContent;button.disabled=true;button.textContent="Lily is writing locally…";try{const kind=button.dataset.aiKind||"description";const d=await localAi("/generate",{method:"POST",body:JSON.stringify({model:selectedAiModel(),task:`write ${kind}`,input:{current:target.value||"",fields,shop:shopSettings||{}},schema:{text:"finished wording"}})});target.value=d.result?.text||"";target.dispatchEvent(new Event("input",{bubbles:true}));toast("Lily added polished wording. Review it, then save.")}catch(e){toast(`Local AI unavailable: ${e.message}`)}finally{button.disabled=false;button.textContent=original}}
