if(t=e.target.closest("[data-delete-order]")){const order=orders.find(x=>String(x.id)===String(t.dataset.deleteOrder));if(!order)return toast("Order not found");if(confirm(`Delete ${order.order_number||"this order"}? Orders with recorded payments cannot be deleted.`)){try{await api("orders",{method:"DELETE",body:JSON.stringify({id:order.id})});if(pendingPaymentOrder?.id===order.id)setPendingPaymentOrder(null);await Promise.all([loadOrders(),loadDashboard()]);if(document.getElementById("invoicesPage")?.classList.contains("active"))await loadInvoices();toast("Order deleted")}catch(err){toast(err.message)}}return}
