$("#checkout").onclick=async()=>{const button=$("#checkout"),status=$("#paymentStatus"),amount=Number($("#paymentAmount").value||0),description=$("#paymentDescription").value.trim();if(amount<0.50){status.textContent="Enter a payment amount of at least $0.50.";$("#paymentAmount").focus();return}try{pendingPaymentOrder=pendingPaymentOrder||JSON.parse(localStorage.getItem("bloom_pending_payment_order")||"null")}catch{}button.disabled=true;button.textContent="Opening Stripe…";status.textContent="Creating a secure checkout session…";try{const d=await api("create-checkout",{method:"POST",body:JSON.stringify({amount,description,order_id:pendingPaymentOrder?.id||"",order_number:pendingPaymentOrder?.order_number||""})});if(!d.url)throw new Error("Stripe did not return a checkout link.");status.textContent="Redirecting to Stripe…";location.assign(d.url)}catch(err){status.textContent=err.message;toast(err.message)}finally{button.disabled=false;button.textContent="Charge card securely"}};
async function finishStripeReturn(){const q=new URLSearchParams(location.search),result=q.get("payment"),sessionId=q.get("session_id");if(!result)return;if(result==="cancelled"){toast("Stripe payment was cancelled. The order is still unpaid.");history.replaceState({},"",location.pathname);return}if(result==="success"&&sessionId){try{const d=await api(`verify-checkout?session_id=${encodeURIComponent(sessionId)}`);if(d.paid){localStorage.removeItem("bloom_pending_payment_order");pendingPaymentOrder=null;toast(`Payment received${d.amount?` — ${money(d.amount)}`:""}`);await Promise.all([loadOrders(),loadDashboard()]);showPage("ordersPage")}else toast("Stripe returned, but the payment is not marked paid yet.")}catch(err){toast(`Payment verification needs attention: ${err.message}`)}finally{history.replaceState({},"",location.pathname)}}}
